package day259

import (
	"sort"
)

// GhostWinningLetterPlayerOne determines the winning starting letters for Player 1 in the Ghost game.
// A letter is a winning start if all words beginning with that letter have even length.
// This ensures that with optimal play, Player 1 cannot lose because Player 2 will be forced
// to spell the complete word (placing the last letter at an even position).
func GhostWinningLetterPlayerOne(dict []string) []rune {
	// Map to track if all words starting with a rune have even length
	// Initialize as true for each rune, set to false if we find any odd-length word
	evenLengthOnly := make(map[rune]bool)

	// Track which runes appear in the dictionary
	runePresent := make(map[rune]bool)

	for _, word := range dict {
		if len(word) == 0 {
			continue
		}

		firstRune := rune(word[0])
		runePresent[firstRune] = true

		// If this word has odd length, then firstRune cannot be a winning start
		if len(word)%2 != 0 {
			evenLengthOnly[firstRune] = false
		}
	}

	// Collect all runes where all words have even length
	var winningLetters []rune
	for r := range runePresent {
		// If not marked as having odd-length words, it's a winning start
		if !evenLengthOnly[r] {
			winningLetters = append(winningLetters, r)
		}
	}

	// Sort the result in ascending order
	sort.Slice(winningLetters, func(i, j int) bool {
		return winningLetters[i] < winningLetters[j]
	})

	return winningLetters
}
